package com.example.location.processor; import com.example.location.model.LocationRequest; import com.example.location.support.ValidationException; import org.apache.camel.*; import org.springframework.stereotype.Component; @Component public class ValidateGetLocationListRequestProcessor implements Processor{ public void process(Exchange ex){ LocationRequest r=ex.getMessage().getBody(LocationRequest.class); boolean any=is(r.postalCode)||is(r.stateOrProvinceCode)||is(r.postalStateAbbreviation)||is(r.locationPlaceCode); if(!any) throw new ValidationException("Required service request data fields are missing: one of PostalCode, LocationPlaceCode, StateOrProvinceCode, PostalStateAbbreviation."); } boolean is(String s){return s!=null&&!s.isBlank();} }